/* @lc app=leetcode id=3603 lang=kotlin */ class Solution { fun minCost(m: Int, n: Int, waitCost: Array<IntArray>): Long = (0 until m).fold(LongArray(n) { Long.MAX_VALUE / 4 }) { prev, i -> LongArray(n).also { cur -> (0 until n).forEach { j -> cur[j] = if (i == 0 && j == 0) 1L else minOf(if (i > 0) prev[j] + (if (i == 1 && j == 0) 0 else waitCost[i - 1][j]) else Long.MAX_VALUE / 4, if (j > 0) cur[j - 1] + (if (i == 0 && j == 1) 0 else waitCost[i][j - 1]) else Long.MAX_VALUE / 4) + (i + 1L) * (j + 1) } } }.last() }